import * as THREE from 'three/webgpu';
import { uv, mix, color, float } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @typedef {Object} NodeConfig
 * @property {Array<Object>} [textContent]
 * @property {Array<Object>} [intent]
 * @property {Array<Object>} [cinematicPrimitives]
 * @property {string} [background]
 * @property {string} [surface]
 * @property {string} [ink]
 * @property {string} [paper]
 * @property {string} [accent]
 * @property {Array<Object>} [gradientStops]
 */

/**
 * @typedef {Object} NodeContext
 * @property {any} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} videoLoader
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} tier
 */

/**
 * Create testimonial panel node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    MeshStandardNodeMaterial,
    DoubleSide,
  } = THREE;

  const root = new Group();

  // ==========================
  // Panel geometry & material
  // ==========================
  const panelWidth = 3.4;
  const panelHeight = 1.9;

  const panelGeom = new PlaneGeometry(panelWidth, panelHeight);
  const panelMat = new MeshStandardNodeMaterial();
  panelMat.side = DoubleSide;
  // vertical engineered gradient
  const v = uv();
  panelMat.colorNode = mix(color('#1a1a22'), color('#111116'), v.y);
  panelMat.roughnessNode = float(0.6);
  panelMat.metalnessNode = float(0.2);
  panelMat.clearcoatNode = float(0.1);
  // hairline border (simple dark overlay)
  // (not geometry‑based; omitted for brevity)

  const panelMesh = new Mesh(panelGeom, panelMat);
  root.add(panelMesh);

  // ==========================
  // Typography via font atlas
  // ==========================
  // Helper to add text objects
  const addText = (content, opts = {}, pos = { x: 0, y: 0, z: 0 }) => {
    const txt = ctx.fontAtlas.createText(content, opts);
    txt.position.set(pos.x, pos.y, pos.z);
    root.add(txt);
    return txt;
  };

  const pad = 0.5; // 2 × base unit (0.25)

  // Quote mark (oversized)
  const qMark = addText('“', {
    fontSize: 62,
    color: '#ff2a38',
    align: 'left',
  });

  // Position quote mark at top‑left inside panel
  const qMarkX = -panelWidth / 2 + pad + 0.62 / 2;
  const qMarkY = panelHeight / 2 - pad - 0.62 / 2;
  qMark.position.set(qMarkX, qMarkY, 0.02); // slight Z for extrusion illusion
  qMark.scale.set(1.04, 1.04, 1.04); // start slightly larger for settle

  // Quote text
  const quoteStr =
    'The bezel action alone is worth the wait. Nothing else on my wrist feels this considered.';
  const quoteTxt = addText(quoteStr, {
    fontSize: 20,
    color: '#16161d',
    align: 'left',
    maxWidthPx: 2400,
  });
  const quoteX = -panelWidth / 2 + pad;
  const quoteY = qMarkY - 0.62 / 2 - 0.25;
  quoteTxt.position.set(quoteX, quoteY, 0.03); // float above panel

  // Accent rule for attribution
  const ruleGeom = new BoxGeometry(0.2, 0.02, 0.001);
  const ruleMat = new MeshStandardNodeMaterial({
    color: '#ff2a38',
    emissive: '#ff2a38',
    emissiveIntensity: 1.4,
    roughness: 0.6,
    metalness: 0.2,
    clearcoat: 0.1,
  });
  const rule = new Mesh(ruleGeom, ruleMat);
  const ruleX = -panelWidth / 2 + pad;
  const ruleY = quoteY - 0.25;
  rule.position.set(ruleX + 0.2 / 2, ruleY - 0.01, 0);
  root.add(rule);

  // Attribution text
  const attribTxt = addText('M. OKAFOR', {
    fontSize: 13,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: 0.08,
  });
  const attribX = rule.position.x + 0.2 / 2 + 0.05;
  const attribY = rule.position.y - 0.02;
  attribTxt.position.set(attribX, attribY, 0.02);

  // Caption text
  const captionTxt = addText('COLLECTOR SINCE 2019', {
    fontSize: 9,
    color: '#e8ecf2',
    align: 'left',
    letterSpacing: 0.12,
  });
  captionTxt.position.set(attribX, attribY - 0.15, 0.02);

  // ==========================
  // Animation timelines
  // ==========================
  const timelines = [];

  // Fade‑up for whole panel
  const fadeTimeline = gsap.timeline({ paused: true });
  panelMesh.visible = true;
  panelMat.transparent = true;
  panelMat.opacity = 0;
  root.position.y += 0.2;
  fadeTimeline.to(
    panelMat,
    { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  fadeTimeline.to(
    root.position,
    { y: root.position.y - 0.2, duration: 0.5, ease: 'cubic-bezier(0.25,0.46,0.45,0.94)' },
    0
  );
  fadeTimeline.play();
  timelines.push(fadeTimeline);

  // Weighted‑settle for quote mark
  const settleTimeline = gsap.timeline({ paused: true, delay: 0.2 });
  settleTimeline.to(
    qMark.scale,
    {
      x: 1,
      y: 1,
      z: 1,
      duration: 0.9,
      ease: 'cubic-bezier(0.165,0.84,0.44,1)',
    },
    0
  );
  settleTimeline.play();
  timelines.push(settleTimeline);

  // ==========================
  // Cleanup & handlers
  // ==========================
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    timelines.forEach((t) => t.kill && t.kill());
    root.traverse((obj) => {
      if (obj.geometry) {
        obj.geometry.dispose();
      }
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose && m.dispose());
        } else {
          obj.material.dispose && obj.material.dispose();
        }
      }
    });
  };

  return root;
}
